mkuse!{use std :: cell :: { Cell , RefCell } ;}
mkuse!{use std :: mem :: MaybeUninit ;}
mkuse!{use std :: ops :: Range ;}
mkuse!{use std :: { cmp , ptr , slice , str } ;}
mkitem!{const PAGE : usize = 4096 ;}
mkitem!{const HUGE_PAGE : usize = 2 * 1024 * 1024 ;}
mkitem!{mkstruct!{# [doc = " A minimal arena allocator inspired by `rustc_arena::DroplessArena`."] # [doc = ""] # [doc = " This is unfortunately a complete re-implementation rather than a dependency"] # [doc = " as it is difficult to depend on crates from within `proc_macro`, due to it"] # [doc = " being built at the same time as `std`."] # [doc = ""] # [doc = " This arena doesn't have support for allocating anything other than byte"] # [doc = " slices, as that is all that is necessary."] pub (crate) struct Arena { start : Cell < * mut MaybeUninit < u8 > > , end : Cell < * mut MaybeUninit < u8 > > , chunks : RefCell < Vec < Box < [MaybeUninit < u8 >] > > > , }}}
mkitem!{mkimpl!{impl Arena { pub (crate) fn new () -> Self { Arena { start : Cell :: new (ptr :: null_mut ()) , end : Cell :: new (ptr :: null_mut ()) , chunks : RefCell :: new (Vec :: new ()) , } } # [doc = " Add a new chunk with at least `additional` free bytes."] # [inline (never)] # [cold] fn grow (& self , additional : usize) { let mut chunks = self . chunks . borrow_mut () ; let mut new_cap ; if let Some (last_chunk) = chunks . last_mut () { new_cap = last_chunk . len () . min (HUGE_PAGE / 2) ; new_cap *= 2 ; } else { new_cap = PAGE ; } new_cap = cmp :: max (additional , new_cap) ; let mut chunk = Box :: new_uninit_slice (new_cap) ; let Range { start , end } = chunk . as_mut_ptr_range () ; self . start . set (start) ; self . end . set (end) ; chunks . push (chunk) ; } # [doc = " Allocates a byte slice with specified size from the current memory"] # [doc = " chunk. Returns `None` if there is no free space left to satisfy the"] # [doc = " request."] # [allow (clippy :: mut_from_ref)] fn alloc_raw_without_grow (& self , bytes : usize) -> Option < & mut [MaybeUninit < u8 >] > { let start = self . start . get () . addr () ; let old_end = self . end . get () ; let end = old_end . addr () ; let new_end = end . checked_sub (bytes) ? ; if start <= new_end { let new_end = old_end . with_addr (new_end) ; self . end . set (new_end) ; Some (unsafe { slice :: from_raw_parts_mut (new_end , bytes) }) } else { None } } fn alloc_raw (& self , bytes : usize) -> & mut [MaybeUninit < u8 >] { if bytes == 0 { return & mut [] ; } loop { if let Some (a) = self . alloc_raw_without_grow (bytes) { break a ; } self . grow (bytes) ; } } # [allow (clippy :: mut_from_ref)] pub (crate) fn alloc_str < 'a > (& 'a self , string : & str) -> & 'a mut str { let alloc = self . alloc_raw (string . len ()) ; let bytes = alloc . write_copy_of_slice (string . as_bytes ()) ; unsafe { str :: from_utf8_unchecked_mut (bytes) } } }}}